cd /mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s03
# Heuristic: for each helper call site, check whether the same function earlier captures skb->data or header pointer via common patterns, i.e. find candidate "save then call then use".
python3 - <<'EOF'
import re, os
calls = {}
with open(os.environ['TMPDIR'] + '/i009_calls.txt') as f:
    for line in f:
        path, ln, rest = line.split(':', 2)
        calls.setdefault(path, []).append((int(ln), rest.rstrip()))

HELP = re.compile(r'\b(pskb_expand_head|skb_realloc_headroom|skb_cow_head|skb_cow|skb_linearize_cow|skb_copy_expand_head|skb_linearize|pskb_trim_rcsum|pskb_carve|pskb_trim)\s*\(')
# patterns indicating a pointer into skb data saved before call
SAVE = re.compile(r'\b\w+\s*=\s*(skb->data|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|skb_header_pointer\s*\(|skb_copy_bits|skb_reset_network_header|skb_reset_transport_header)\b')
out = []
for path, lst in calls.items():
    try:
        src = open(path, errors='replace').read().splitlines()
    except OSError:
        continue
    # find function boundaries roughly by lines starting with non-whitespace containing '('
    fn_starts = [i for i, l in enumerate(src) if re.match(r'^[A-Za-z_].*\(', l)]
    def fname_of(idx):
        for i in range(idx, -1, -1):
            m = re.match(r'^[A-Za-z_][\w\s\*]*?(\w+)\s*\(', src[i])
            if m:
                return m.group(1), i
        return None, 0
    for ln, text in lst:
        idx = ln - 1
        fname, fstart = fname_of(idx)
        # search backwards within 120 lines of the call for a save of skb->data etc.
        hits = []
        for j in range(max(0, idx-120), idx):
            l = src[j]
            m = re.search(r'(\w+)\s*=\s*(?:skb->data|skb_header_pointer\s*\(.*|skb_network_header\s*\(\w+\)|skb_transport_header\s*\(\w+\)|skb_mac_header\s*\(\w+\))', l)
            if m:
                hits.append((j+1, l.strip()))
        if hits:
            out.append((path, ln, fname, fstart+1, text.strip(), hits))
print(len(out))
for path, ln, fname, fstart, text, hits in out:
    print(f"{path}:{ln} in {fname} (fn@{fstart}) call: {text}")
    for h in hits[-4:]:
        print(f"    save@{h[0]}: {h[1]}")
EOF

