    for (fs, fe, fname) in func_spans(text):
        body = [(idx, strip_line(lines[idx])) for idx in range(fs, fe+1)]
        helper_lines = [idx for (idx, l) in body if HELPER_RE.search(l)]
        if not helper_lines:
            continue
        first_helper = min(helper_lines)
        last_helper = max(helper_lines)
        # derive pointer declarations before first helper call
        derived = {}
        for (idx, l) in body:
            if idx >= first_helper:
                break
            m = DERIV_RE.match(l)
            if m and DERIV_HINT.search(m.group(2)):
                derived[m.group(1)] = (idx+1, m.group(2).strip())
        if not derived:
            continue
        for (idx, l) in body:
            if idx <= last_helper:
                continue
            for name, (dl, dexpr) in derived.items():
                pat = re.escape(name)
                if re.search(r"\b" + pat + r"\b\s*(->|\[|\.\w|\+|\-|\+\+|==|!=)", l) or \
                   re.search(r"(->|\+|\*|&|\[|,|\()\s*" + pat + r"\b", l) or \
                   re.search(r"return\s+" + pat + r"\s*;", l):
                    if re.search(r"\b" + pat + r"\s*=\s*[^=]", l):
                        continue  # reassignment (possible refetch)
                    results.append({
                        "file": path, "func": fname,
                        "derive_line": dl, "derive_expr": dexpr,
                        "helper_first": first_helper+1, "helper_last": last_helper+1,
                        "use_line": idx+1, "use_text": lines[idx].strip()[:160],
                    })
    return results

def main():
    all_res = []
    for base in ("net", "drivers/net"):
        for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, base)):
            for fn in filenames:
                if not fn.endswith((".c", ".h")):
                    continue
                p = os.path.join(dirpath, fn)
                try:
                    text = open(p, encoding="utf-8", errors="replace").read()
                except OSError:
                    continue
                rel = os.path.relpath(p, ROOT)
                all_res.extend(analyze(rel, text))
    for r in all_res:
        print(f"{r['file']} :: {r['func']} :: derive@{r['derive_line']} [{r['derive_expr'][:70]}] helper@{r['helper_first']}-{r['helper_last']} use@{r['use_line']}: {r['use_text']}")
    print(f"TOTAL {len(all_res)}", file=sys.stderr)

main()
