T="$TMPDIR/i009"; cat > "$T/scan.py" << 'EOF'
import re, os, sys

HELPERS = ['pskb_expand_head','skb_realloc_headroom','skb_cow_head','skb_cow','skb_linearize_cow','skb_linearize','pskb_trim_rcsum','pskb_trim','pskb_carve','skb_copy_expand_head']
# pointer acquisition patterns into skb data area
ACQ = re.compile(r'''
 ^(?P<ind>[^\s].*)$
''', re.X)

acq_pat = re.compile(r'\b(?:struct\s+)?(\w+)\s*\*\s*(\w+)\s*=\s*(?:skb_header_pointer\s*\(\s*skb|(\w+)\s*\(\s*skb|skb_->data|skb->data|skb_network_header\s*\(\s*skb|skb_transport_header\s*\(\s*skb|skb_mac_header\s*\(\s*skb)', re.X)

def read_funcs(path):
    src = open(path, encoding='utf-8', errors='replace').read().splitlines()
    funcs = []  # (start, end, name)
    i = 0
    n = len(src)
    while i < n:
        line = src[i]
        m = re.match(r'^(?:static\s+)?(?:inline\s+)?(?:const\s+)?[\w\*\/\s]+\b(\w+)\s*\(', line)
        if m and not line.strip().startswith(('#','//','*')) and '=' not in line.split('(')[0] and line.rstrip().endswith(')') is False and ('{' in line or (i+1 < n and src[i+1].strip() == '{')):
            name = m.group(1)
            # find opening brace
            j = i
            depth = 0
            started = False
            while j < n and j < i + 400:
                for ch in src[j]:
                    if ch == '{':
                        depth += 1; started = True
                    elif ch == '}':
                        depth -= 1
                        if started and depth == 0:
                            funcs.append((i, j, name))
                            break
                if started and depth <= 0:
                    break
                j += 1
            if started and depth == 0:
                i = j + 1
                continue
        i += 1
    return src, funcs

results = []
root = sys.argv[1]
for dirpath, dirs, files in os.walk(root):
    if '/net' not in dirpath and 'drivers/net' not in dirpath:
        continue
    for f in files:
        if not f.endswith('.c'):
            continue
        p = os.path.join(dirpath, f)
        try:
            src, funcs = read_funcs(p)
        except Exception as e:
            continue
        for (s, e, name) in funcs:
            body = src[s:e+1]
            # find helper call lines
            for idx, line in enumerate(body):
                for h in HELPERS:
                    if re.search(r'\b'+h+r'\s*\(', line):
                        # find acquires before and uses after within function
                        before = body[:idx]
                        after = body[idx+1:]
                        acqnames = set()
                        for b in before:
                            for m in acq_pat.finditer(b):
                                acqnames.add(m.group(2))
                        # also simple "x = ..._hdr(skb)" for any word
                        for b in before:
                            m2 = re.match(r'\s*(?:const\s+)?(?:struct\s+)?[\w\s\*]*?(\w+)\s*=\s*(\w+)\s*\(\s*skb\s*\)', b)
                            if m2 and m2.group(2).endswith('_hdr'):
                                acqnames.add(m2.group(1))
                            m3 = re.match(r'\s*(?:const\s+)?(?:struct\s+)?[\w\s\*]*?(\w+)\s*=\s*skb->data', b)
                            if m3:
                                acqnames.add(m3.group(1))
                        if not acqnames:
                            continue
                        uses = []
                        for a in after:
                            for an in acqnames:
                                if re.search(r'\b'+re.escape(an)+r'\b', a):
                                    uses.append((s+idx+1, a.strip()))
                        if uses:
                            results.append((p, s+idx+1, name, h, sorted(acqnames), uses[:6]))
for r in results:
    print(r[0], r[1], r[2], r[3], 'acq=', r[4], 'use@', r[5])
EOF
python3 "$T/scan.py" snapshots/s03 > "$T/scan_out.txt" 2>&1; wc -l < "$T/scan_out.txt"; head -80 "$T/scan_out.txt"

